INSERT INTO "community_blends" (id,creator_id,creator_name,creator_avatar,creator_bio,name,slug,description,story,recipe,revelation_data,price,visibility,status,consent_to_share,consent_date,original_order_id,purchase_verified_at,view_count,purchase_count,rating_sum,rating_count,popularity_score,created_at,updated_at,published_at) VALUES ('b34789bf-b107-4222-9c95-76bbfb4fbdc5','oil-amor-admin','Oil Amor',NULL,'Artisan essential oil blends crafted with intention in the Oil Amor Atelier.','67 Lemon','67-lemon','A bright, uplifting citrus-forward blend with warm woody undertones and a gentle spice finish. Named for the year o
  f transformation — 1967 — this blend captures the spirit of renewal, clarity, and joyful energy. Lemongrass leads with
  its crisp, lemony vibrancy, supported by the creamy sweetness of Ho Wood and the sacred depth of Frankincense. Cedarwo
  od grounds the composition, while Ginger and Clove Bud add a subtle warming spice that lingers beautifully on the skin
  .','The "67 Lemon" blend was born from a desire to capture the essence of a perfect summer morning — when sunlight filt
  ers through lemon trees and the air is alive with possibility. Each oil was selected not just for its individual chara
  cter, but for how they harmonise: Lemongrass brings the brightness, Ho Wood the softness, Frankincense the sacred paus
  e, Cedarwood the earth, and Ginger & Clove Bud the warm embrace. It is a blend for those who seek clarity with comfort
  , energy with grounding.','[object Object]',NULL,'2995','community','published','true','Wed Apr 29 2026 13:55:46 GMT+1000 (Australian Eastern Standard Time)',NULL,'Wed Apr 29 2026 13:55:46 GMT+1000 (Australian Eastern Standard Time)','6','0','0','0','0','Wed Apr 29 2026 13:55:46 GMT+1000 (Australian Eastern Standard Time)','Sun Sep 06 2026 22:23:49 GMT+1000 (Australian Eastern Standard Time)','Wed Apr 29 2026 13:55:46 GMT+1000 (Australian Eastern Standard Time)');

